stdlib/grpc/grpc.kav:
use std.grpc.frames

use std.grpc.protobuf

use std.http.h2

use std.http.hpack

use std.json

use std.net

/// A call as a server's handler gets it: the method's path and the
/// messages the client sent, still encoded (`read` and `read_all` decode
/// them). `message` is the first; a client that streams sends several.
pub type GrpcCall {
    pub method: String
    pub message: Bytes
    pub messages: [Bytes]
}

/// A server's answer: a message, a stream of messages, or a gRPC
/// status other than OK.
pub type GrpcReply = Message(data: Bytes) | Stream(messages: [Bytes]) | Failed(code: Int, message: String)

/// `value` as a Protocol Buffers message.
pub fn encode<T>(value: T) -> Bytes { … }

/// A Protocol Buffers message decoded into a `T`.
pub fn decode<T>(data: Bytes) -> T ! GrpcError { … }

/// A call's message decoded into a `T`.
pub fn read<T>(call: GrpcCall) -> T ! GrpcError { … }

/// Every message the client sent on `call`, in order, each decoded into a `T`.
pub fn read_all<T>(call: GrpcCall) -> [T] ! GrpcError { … }

/// An answer with `value`.
pub fn reply<T>(value: T) -> GrpcReply { … }

/// An answer that streams `values`, one message each (spec 14.14).
pub fn reply_stream<T>(values: [T]) -> GrpcReply { … }

/// An answer with gRPC status `code` (not 0) and `message`.
pub fn failed(code: Int, message: String) -> GrpcReply { … }

/// Calls `method` (`/shop.Orders/Place`) on the server at `target`
/// (`http://host:port`, or `https://` for TLS) with `request`.
pub fn call<Req, Res>(target: String, method: String, request: Req) -> Res ! GrpcError uses Net { … }

/// Client streaming: calls `method` with each of `requests` as its own
/// message on one stream, and decodes the one answer.
pub fn call_stream<Req, Res>(target: String, method: String, requests: [Req]) -> Res ! GrpcError uses Net { … }

/// Calls streaming `method` on the server at `target` with `request`,
/// running `on` for each message as it arrives; returns when the server
/// finishes with status OK, and fails with `Status` otherwise.
pub fn each<Req, Res>(target: String, method: String, request: Req, on: fn(Res)) ! GrpcError uses Net { … }

/// Two-way streaming: sends each of `requests` on one stream, ends the
/// client's side, then runs `on` for each answer as it arrives, like `each`.
pub fn each_stream<Req, Res>(target: String, method: String, requests: [Req], on: fn(Res)) ! GrpcError uses Net { … }

/// A two-way conversation: sends `first`, then runs `on` for each answer
/// as it arrives; `on` gives the messages to send next, or none to end
/// the client's side. Returns when the server finishes with status OK.
pub fn talk_with<Req, Res>(target: String, method: String, first: [Req], on: fn(Res) -> [Req]?) ! GrpcError uses Net { … }

/// A connection to `target`, and the headers that open a call to `method`.
type Opening {
    conn: Connection
    headers: [Header]
}

fn opening(target: String, method: String) -> Opening ! GrpcError uses Net { … }

/// Sends `body` (framed messages) and decodes the one answer.
fn answer<Res>(target: String, method: String, body: Bytes) -> Res ! GrpcError uses Net { … }

/// Sends `body` (framed messages), then runs `on` for each answer as it
/// arrives, until the server's status.
fn answers<Res>(target: String, method: String, body: Bytes, on: fn(Res)) ! GrpcError uses Net { … }

/// Serves gRPC on `listener`: each connection in a task of its own, each
/// call answered by `handler`.
pub fn serve(listener: Listener, handler: fn(GrpcCall) -> GrpcReply) ! NetError uses Net { … }

/// Serves gRPC like `serve`, but holds a conversation on each method in
/// `talks`: `handler` answers each of its messages as soon as it arrives,
/// and the answer goes back at once (spec 14.14).
pub fn serve_talks(listener: Listener, handler: fn(GrpcCall) -> GrpcReply, talks: [String]) ! NetError uses Net { … }

/// A call being received on one stream.
type Calling {
    method: String
    body: Bytes
    /// A conversation: each message is answered as it arrives.
    talk: Bool
    /// A conversation the handler ended early with a failure.
    over: Bool
}

fn ok_headers() -> [Header] { … }

/// The calls of one connection, until the client is done: a talk's
/// messages are answered as they arrive, other calls once they end.
fn answer_all(conn: Connection, handler: fn(GrpcCall) -> GrpcReply, talks: [String]) ! H2Error uses Net { … }

/// Answers a call that has all its messages, with `handler`.
fn answer_whole(link: Link, stream: Int, call: Calling, handler: fn(GrpcCall) -> GrpcReply) -> Link ! H2Error uses Net { … }

/// A reply's messages, each behind its prefix (none for a failure).
fn answer_body(reply: GrpcReply) -> Bytes { … }

/// Each of `values` as a message behind its prefix, one after another.
fn framed_all<T>(values: [T]) -> Bytes { … }

stdlib/grpc/protobuf.kav:
use std.json

/// Why a message can't be read, or a value can't be sent.
pub type ProtoError = Malformed(reason: String) | Unsupported(reason: String)

/// A field as the wire carries it (wire types 0, 1, 2 and 5).
type Raw = Varint(value: UInt64) | Fixed64(value: UInt64) | Chunk(data: Bytes) | Fixed32(value: UInt64)

/// A number read from `data`, and where the bytes after it start.
type Read {
    value: UInt64
    next: Int
}

/// `value` (as `json.of` gives it) as a message with `schema`'s fields.
pub fn encode(value: Json, schema: Json) -> Bytes ! ProtoError { … }

/// A message `data` as a `Json` object with `schema`'s fields: a field
/// that isn't there is `null`, or its type's zero value.
pub fn decode(data: Bytes, schema: Json) -> Json ! ProtoError { … }

/// The field `n` with value `v` of schema `s`; nothing for `null`.
fn field(n: Int, v: Json, s: Json) -> Bytes ! ProtoError { … }

/// A number or boolean without its key: a varint, or 8 bytes for a
/// `double`.
fn plain(v: Json, s: Json) -> Bytes ! ProtoError { … }

/// Whether a list of `s` goes packed (numbers and booleans).
fn scalar(s: Json) -> Bool { … }

/// The key of field `n` with wire type `wire`.
fn key(n: Int, wire: Int) -> Bytes
    require n >= 1 and n < 536_870_912
    require wire >= 0 and wire <= 5
{ … }

/// A length-delimited field `n`.
fn chunk(n: Int, data: Bytes) -> Bytes
    require n >= 1 and n < 536_870_912
{ … }

/// `n` as a varint; a negative `n` takes ten bytes, as `int64` does.
pub fn varint(n: Int) -> Bytes
    example varint(1) == Bytes([UInt8(1)])
    example varint(150) == Bytes([UInt8(150), UInt8(1)])
    example varint(-1).len() == 10
{ … }

/// The varint at `at` in `data`.
fn read_varint(data: Bytes, at: Int) -> Read ! ProtoError
    require at >= 0
{ … }

/// `n` bytes at `at`, little-endian.
fn read_fixed(data: Bytes, at: Int, n: Int) -> UInt64 ! ProtoError
    require at >= 0
    require n >= 0 and n <= 8
{ … }

/// The fields of message `data`, by number, in the order they came.
fn fields(data: Bytes) -> [Int: [Raw]] ! ProtoError { … }

/// The `Json` of a field of schema `s` that came as `raws` (none, one,
/// or several for a repeated field).
fn value_of(raws: [Raw], s: Json) -> Json ! ProtoError { … }

/// One value of schema `s`.
fn one(r: Raw, s: Json) -> Json ! ProtoError { … }

/// The value of a field that isn't there.
fn zero(s: Json) -> Json ! ProtoError { … }

/// A union value as its wrapper message (spec 14.14): counting the
/// fieldless variants first, variant `k` is field `k` — an empty message
/// for a fieldless one, the variant's fields as a message otherwise.
fn union_bytes(v: Json, opts: [Json]) -> Bytes ! ProtoError { … }

/// The variant a wrapper message holds, back as `json.of` writes it.
fn union_value(data: Bytes, opts: [Json]) -> Json ! ProtoError { … }

/// The fieldless variant names of a union schema, in order.
fn plain_names(opts: [Json]) -> [String] { … }

/// The variant-with-fields options of a union schema, in order.
fn fielded(opts: [Json]) -> [Json] { … }

fn number(bits: UInt64) -> Json { … }

/// An `int64` read as a varint: above `Int`'s largest, it is negative.
fn signed(u: UInt64) -> Int { … }

stdlib/http/h2.kav:
use std.net

use std.http.hpack

use std.http.h2.wire

pub use std.http.h2.client.{H2Client, connect}

/// What `next` found: the link, and a request unless the client is done.
pub type Next {
    pub link: Link
    pub message: H2Message?
}

/// Sends one request on stream 1 of a new connection and reads the
/// response. `headers` has `:method`, `:scheme`, `:authority`, `:path`.
pub fn request(conn: Connection, headers: [Header], body: Bytes) -> H2Message ! H2Error uses Net { … }

/// Opens a request without waiting for the answer: `pull` then reads
/// it as it arrives (spec 14.14 streams on this).
pub fn open(conn: Connection, headers: [Header], body: Bytes) -> Link ! H2Error uses Net { … }

/// Opens a request on stream 1 of a new connection and leaves the
/// stream open: `send_data` sends its body piece by piece, and `pull`
/// reads the answer as it arrives, so both can go on at once.
pub fn begin(conn: Connection, headers: [Header]) -> Link ! H2Error uses Net { … }

/// Sends `data` on `stream`; `end` ends this side of the stream.
pub fn send_data(link: Link, stream: Int, data: Bytes, end: Bool) -> Link ! H2Error uses Net { … }

/// Sends a response's headers on `stream` and leaves it open for
/// `send_data` and `send_trailers`.
pub fn send_headers(link: Link, stream: Int, headers: [Header]) -> Link ! H2Error uses Net { … }

/// Sends header fields after the body (trailers), ending the stream.
pub fn send_trailers(link: Link, stream: Int, trailers: [Header]) -> Link ! H2Error uses Net { … }

/// What `pull` found: body bytes that arrived (maybe none yet), and the
/// trailing headers once the answer ended.
pub type Pulled {
    pub link: Link
    pub data: Bytes
    pub ended: Bool
    pub trailers: [String: String]
}

/// The next piece of the answer on stream 1: waits until bytes arrive
/// or the answer ends.
pub fn pull(link: Link) -> Pulled ! H2Error uses Net { … }

/// Starts the server side of a connection that began with `data` (the
/// preface, or its start).
pub fn accept(conn: Connection, data: Bytes) -> Link ! H2Error uses Net { … }

/// The next whole request, or none once the client is done.
pub fn next(link: Link) -> Next ! H2Error uses Net { … }

/// What happened on a server's connection, in the order it happened.
pub type H2Event = StreamOpened(stream: Int, headers: [String: String]) |
    StreamData(stream: Int, data: Bytes) |
    StreamEnded(stream: Int) |
    ClientDone

/// What `watch` found: the link, and the event.
pub type H2Watched {
    pub link: Link
    pub event: H2Event
}

/// The server side, piece by piece: a request's headers as soon as they
/// arrive, then its body bytes as they arrive, then its end; `ClientDone`
/// once the client is done. Use it instead of `next`, never with it.
pub fn watch(link: Link) -> H2Watched ! H2Error uses Net { … }

/// Sends a response on `stream`; `headers` starts with `:status`.
pub fn respond(link: Link, stream: Int, headers: [Header], body: Bytes) -> Link ! H2Error uses Net { … }

/// Sends a response on `stream` with header fields after its body
/// (trailers), as gRPC sends its status.
pub fn respond_with_trailers(
    link: Link,
    stream: Int,
    headers: [Header],
    body: Bytes,
    trailers: [Header],
) -> Link ! H2Error uses Net { … }

stdlib/http/h2client.kav:
use std.net

use std.http.h2.wire

use std.http.h2.wire.{Credit}

/// A connection for many requests, from `h2.connect`.
pub type H2Client {
    /// The turn to send, with what sending needs.
    send_turn: Receiver<Sending>
    send_back: Sender<Sending>
    /// The connection's reading side, taken by the task that reads.
    read_turn: Receiver<Link>
    read_back: Sender<Link>
    /// What the server lets this side send, as the reader last saw it,
    /// and a signal the reader gives after each frame, for a sender
    /// waiting for credit while another task reads.
    credit: Shared<Credit>
    credit_signal: Receiver<Bool>
    signal_credit: Sender<Bool>
    /// Whether a task is reading, and where each answer still awaited
    /// goes: one task reads at a time and hands each answer to its task
    /// as soon as it is whole, in whatever order the server sends them.
    waiting: Shared<Waiting>
    leaving: Shared<Bool>
}

/// The sending side: the next stream's number, and how much was sent on
/// the connection and on each stream, to set against the server's credit.
type Sending {
    conn: Connection
    next: Int
    sent: Int
    sent_on: [Int: Int]
}

/// Whether a task reads now, and the streams whose answers are awaited.
type Waiting {
    reading: Bool
    streams: [Int: Sender<Got>]
}

/// What a waiting task is told: its answer, that it reads now, or why
/// its request failed.
type Got = Answer(message: H2Message) | Read | Failed(error: H2Error)

/// Starts an HTTP/2 connection on `conn` for many requests.
pub fn connect(conn: Connection) -> H2Client ! H2Error uses Net { … }

fn closed() -> H2Error { … }

extend H2Client {
    /// Sends one request and reads its response. `headers` has
    /// `:method`, `:scheme`, `:authority`, `:path`.
    pub fn request(self, headers: [Header], body: Bytes) -> H2Message ! H2Error uses Net { … }

    /// Whether the server said it is going away (GOAWAY), or the
    /// connection broke: a pool then replaces it with a new one.
    pub fn going_away(self) -> Bool { … }

    /// Closes the connection, once the request being sent is sent. A
    /// request after it fails, and so does one still waiting.
    pub fn close(self) uses Net { … }

    /// Sends a request on the next stream, in its turn: the stream, and
    /// where its answer will come. The answer is awaited from before the
    /// request is sent, so it can't come first.
    fn send_request(self, headers: [Header], body: Bytes) -> (Int, Receiver<Got>) ! H2Error uses Net { … }

    /// Writes a request's header block, as one write so nothing comes
    /// between its frames, then its body as the server's credit allows.
    fn write_request(self, sending: Sending, stream: Int, headers: [Header], body: Bytes) -> Sending ! H2Error uses Net { … }

    /// The answer on `stream`: handed over by the task reading, or read
    /// in turn when no task is reading.
    fn answer(self, stream: Int, hear: Receiver<Got>) -> H2Message ! H2Error uses Net { … }

    /// Whether this task reads now: when its answer was handed over
    /// already, or another task reads, it waits instead.
    fn start_reading(self, stream: Int) -> Role { … }

    /// Stops reading, done with `stream`: another task still waiting
    /// reads on, or none.
    fn stop_reading(self, stream: Int) { … }

    /// No answer is awaited on `stream` any more.
    fn forget(self, stream: Int) { … }

    /// Reads one frame, shares what it changed, and hands each whole
    /// answer, reset or end to the task awaiting it: `stream`'s own
    /// answer is given back instead. A broken connection fails every
    /// request awaited.
    fn read_and_hand_out(self, stream: Int) -> H2Message? ! H2Error uses Net { … }

    /// Hands `got` to the task awaiting `stream`, which then awaits it no
    /// more; nothing when none does.
    fn tell(self, stream: Int, got: Got) { … }

    /// Fails every request awaited with `e`.
    fn fail_all(self, e: H2Error) { … }

    /// A broken connection takes no more requests; a stream the server
    /// reset leaves it usable.
    fn broken_by(self, e: H2Error) { … }
}

/// Whether a task reads the connection now, or waits.
type Role = Read | Wait

